"""OpenAI-compatible chat client interface, a deterministic scripted stub, and
planner/editor model routing.

Nebius Token Factory exposes an OpenAI-compatible API. Per the Token Factory
quickstart (https://docs.tokenfactory.nebius.com/quickstart, retrieved
2026-10-04) the client is configured with::

    base_url="https://api.tokenfactory.nebius.com/v1/"
    api_key=os.environ.get("NEBIUS_API_KEY")

and requests go to ``POST {base_url}chat/completions``. Swapping the scripted
stub for Token Factory is therefore a backend + base_url + key change (see
:func:`make_client`).

Default model IDs are NVIDIA Nemotron models named in the Token Factory docs
(https://docs.tokenfactory.nebius.com/august-2026-deprecation-notice lists
``nvidia/nemotron-3-super-120b-a12b`` and ``nvidia/Nemotron-3_5-Lightning`` as
current replacement models). Confirm both in the live model catalog before use;
override via TESTPILOT_PLANNER_MODEL / TESTPILOT_EDITOR_MODEL.
"""
from __future__ import annotations

import json
import os
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Protocol

TOKEN_FACTORY_BASE_URL = "https://api.tokenfactory.nebius.com/v1/"
TOKEN_FACTORY_DOCS = "https://docs.tokenfactory.nebius.com/quickstart"
DEFAULT_PLANNER_MODEL = "nvidia/nemotron-3-super-120b-a12b"
DEFAULT_EDITOR_MODEL = "nvidia/Nemotron-3_5-Lightning"


class ModelError(RuntimeError):
    pass


class ScriptExhausted(ModelError):
    pass


@dataclass
class Usage:
    prompt_tokens: int
    completion_tokens: int
    estimated: bool = False

    @property
    def total_tokens(self) -> int:
        return self.prompt_tokens + self.completion_tokens


@dataclass
class ChatResponse:
    content: str
    model: str
    usage: Usage
    raw: dict | None = None


class ChatClient(Protocol):
    def chat(self, model: str, messages: list[dict], *, temperature: float = 0.2,
             max_tokens: int | None = None) -> ChatResponse: ...


def estimate_tokens(text: str) -> int:
    """Rough chars/4 token estimate; used only when no API usage is available."""
    return max(1, (len(text) + 3) // 4)


def _messages_text(messages: list[dict]) -> str:
    return "\n".join(str(m.get("content", "")) for m in messages)


# --------------------------------------------------------------------------- stub
class ScriptedModel:
    """Deterministic stand-in for an LLM: replays canned responses in order.

    Every call is recorded in ``self.calls`` (model, messages) so tests can
    assert on routing and prompts. Token usage is a deterministic estimate.
    """

    def __init__(self, responses: list[str] | Callable[[str, list[dict]], str], name: str = "scripted"):
        self._responses = responses if callable(responses) else list(responses)
        self.name = name
        self.calls: list[tuple[str, list[dict]]] = []

    @classmethod
    def from_dir(cls, path: str | Path) -> "ScriptedModel":
        files = sorted(p for p in Path(path).iterdir() if p.suffix in (".md", ".txt") and p.is_file())
        if not files:
            raise ModelError(f"no *.md/*.txt responses in script dir {path}")
        return cls([p.read_text(encoding="utf-8") for p in files], name=f"scripted:{Path(path).name}")

    def chat(self, model: str, messages: list[dict], *, temperature: float = 0.2,
             max_tokens: int | None = None) -> ChatResponse:
        self.calls.append((model, messages))
        if callable(self._responses):
            content = self._responses(model, messages)
        else:
            if not self._responses:
                raise ScriptExhausted(f"{self.name}: script exhausted after {len(self.calls) - 1} calls")
            content = self._responses.pop(0)
        usage = Usage(estimate_tokens(_messages_text(messages)), estimate_tokens(content), estimated=True)
        return ChatResponse(content=content, model=model, usage=usage)


# --------------------------------------------------------------------- real client
Transport = Callable[[str, dict, bytes, float], dict]


def _urllib_transport(url: str, headers: dict, body: bytes, timeout: float) -> dict:
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=timeout) as resp:  # noqa: S310 (https URL from config)
        return json.loads(resp.read().decode("utf-8"))


class OpenAICompatClient:
    """Minimal stdlib client for any OpenAI-compatible ``/chat/completions`` API."""

    RETRY_STATUS = {429, 500, 502, 503, 504}

    def __init__(self, base_url: str = TOKEN_FACTORY_BASE_URL, api_key: str | None = None, *,
                 timeout: float = 120.0, retries: int = 2, transport: Transport | None = None,
                 sleep: Callable[[float], None] = time.sleep):
        if not api_key:
            raise ModelError("API key missing (set NEBIUS_API_KEY)")
        self.base_url = base_url.rstrip("/") + "/"
        self._api_key = api_key
        self.timeout = timeout
        self.retries = retries
        self._transport = transport or _urllib_transport
        self._sleep = sleep

    def chat(self, model: str, messages: list[dict], *, temperature: float = 0.2,
             max_tokens: int | None = None) -> ChatResponse:
        payload: dict = {"model": model, "messages": messages, "temperature": temperature}
        if max_tokens is not None:
            payload["max_tokens"] = max_tokens
        headers = {"Content-Type": "application/json", "Accept": "application/json",
                   "Authorization": f"Bearer {self._api_key}"}
        url = self.base_url + "chat/completions"
        body = json.dumps(payload).encode("utf-8")
        attempt = 0
        while True:
            try:
                data = self._transport(url, headers, body, self.timeout)
                break
            except urllib.error.HTTPError as e:
                if e.code in self.RETRY_STATUS and attempt < self.retries:
                    attempt += 1
                    self._sleep(2 ** attempt)
                    continue
                try:
                    detail = e.read().decode("utf-8", "replace")[:500] if hasattr(e, "read") else ""
                except TimeoutError:
                    # Preserve a terminal status even if its diagnostic body stalls.
                    detail = "response body timed out"
                finally:
                    e.close()
                raise ModelError(f"HTTP {e.code} from {url}: {detail}") from e
            except (urllib.error.URLError, TimeoutError) as e:
                # urllib can raise TimeoutError directly while reading a response body.
                if attempt < self.retries:
                    attempt += 1
                    self._sleep(2 ** attempt)
                    continue
                reason = e.reason if isinstance(e, urllib.error.URLError) else str(e)
                raise ModelError(f"connection error to {url}: {reason}") from e
        try:
            content = data["choices"][0]["message"]["content"] or ""
        except (KeyError, IndexError, TypeError) as e:
            raise ModelError(f"unexpected response shape: {str(data)[:300]}") from e
        u = data.get("usage") or {}
        if "prompt_tokens" in u:
            usage = Usage(int(u.get("prompt_tokens", 0)), int(u.get("completion_tokens", 0)))
        else:
            usage = Usage(estimate_tokens(_messages_text(messages)), estimate_tokens(content), estimated=True)
        return ChatResponse(content=content, model=data.get("model", model), usage=usage, raw=data)


# ------------------------------------------------------------------------ routing
@dataclass
class RoutingConfig:
    """Which model does which job, plus per-model prices for the cost ledger.

    ``prices`` maps model id -> (USD per 1M input tokens, USD per 1M output
    tokens). It is empty by default: fill it from the Token Factory pricing page
    (or TESTPILOT_PRICES='{"model": [in, out]}') — TestPilot does not guess.
    """

    planner_model: str = DEFAULT_PLANNER_MODEL
    editor_model: str = DEFAULT_EDITOR_MODEL
    prices: dict[str, tuple[float, float]] = field(default_factory=dict)

    @classmethod
    def from_env(cls, env: dict | None = None) -> "RoutingConfig":
        env = os.environ if env is None else env
        prices = {k: (float(v[0]), float(v[1])) for k, v in json.loads(env.get("TESTPILOT_PRICES", "{}")).items()}
        return cls(
            planner_model=env.get("TESTPILOT_PLANNER_MODEL", DEFAULT_PLANNER_MODEL),
            editor_model=env.get("TESTPILOT_EDITOR_MODEL", DEFAULT_EDITOR_MODEL),
            prices=prices,
        )

    def model_for(self, role: str) -> str:
        if role == "planner":
            return self.planner_model
        if role in ("editor", "repair"):
            return self.editor_model
        raise ValueError(f"unknown role {role!r}")

    def cost(self, model: str, usage: Usage) -> float:
        pin, pout = self.prices.get(model, (0.0, 0.0))
        return usage.prompt_tokens * pin / 1e6 + usage.completion_tokens * pout / 1e6

    def has_price(self, model: str) -> bool:
        return model in self.prices


def make_client(backend: str | None = None, *, script: str | Path | None = None,
                base_url: str | None = None, api_key: str | None = None,
                env: dict | None = None) -> ChatClient:
    """Build a client. ``backend`` is ``scripted`` (default) or ``tokenfactory``/``openai``."""
    env = os.environ if env is None else env
    backend = (backend or env.get("TESTPILOT_BACKEND") or "scripted").lower()
    if backend == "scripted":
        script = script or env.get("TESTPILOT_SCRIPT")
        if not script:
            raise ModelError("scripted backend needs --script DIR (or TESTPILOT_SCRIPT)")
        return ScriptedModel.from_dir(script)
    if backend in ("tokenfactory", "openai"):
        return OpenAICompatClient(
            base_url=base_url or env.get("TESTPILOT_BASE_URL") or TOKEN_FACTORY_BASE_URL,
            api_key=api_key or env.get("NEBIUS_API_KEY"),
        )
    raise ModelError(f"unknown backend {backend!r}")

files.testpilot/sandbox.py:
"""Run pytest against a throwaway copy of a repo, with a wall-clock timeout.

Isolation is process-level only: a temp copy of the repo, a fresh process
group killed on timeout, and an environment with credential-looking variables
removed. It is NOT a security boundary against hostile code — run TestPilot in
a container/VM for untrusted repos.
"""
from __future__ import annotations

import json
import os
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import xml.etree.ElementTree as ET
from dataclasses import asdict, dataclass, field
from functools import lru_cache
from pathlib import Path, PurePosixPath

IGNORE = shutil.ignore_patterns(".git", "__pycache__", ".pytest_cache", ".venv", "venv",
                                "*.pyc", ".coverage", "node_modules", ".mypy_cache")
_SECRET_MARKERS = ("KEY", "TOKEN", "SECRET", "PASSWORD", "CREDENTIAL")
_OMIT = "*/tests/*,*/test_*.py,*_test.py,*/conftest.py"


@dataclass
class CaseResult:
    nodeid: str
    outcome: str  # passed | failed | error | skipped
    message: str = ""
    generated_file: str | None = None


@dataclass
class CoverageReport:
    percent_total: float
    files: dict[str, dict[str, list[int]]] = field(default_factory=dict)

    def executed(self, path: str) -> set[int]:
        return set(self.files.get(path, {}).get("executed", []))

    def executable(self, path: str) -> set[int]:
        f = self.files.get(path, {})
        return set(f.get("executed", [])) | set(f.get("missing", []))


@dataclass
class SandboxResult:
    returncode: int | None
    timed_out: bool
    duration_s: float
    timeout_s: float
    output: str
    cases: list[CaseResult] = field(default_factory=list)
    coverage: CoverageReport | None = None
    generated_files: list[str] = field(default_factory=list)
    junit_available: bool = False

    def _count(self, outcome: str) -> int:
        return sum(1 for c in self.cases if c.outcome == outcome)

    @property
    def passed(self) -> int:
        return self._count("passed")

    @property
    def failed(self) -> int:
        return self._count("failed")

    @property
    def errors(self) -> int:
        return self._count("error")

    @property
    def skipped(self) -> int:
        return self._count("skipped")

    @property
    def generated_cases(self) -> list[CaseResult]:
        return [c for c in self.cases if c.generated_file in self.generated_files]

    def generated_counts(self) -> dict[str, int] | None:
        if not self.generated_files:
            return None
        cases = self.generated_cases
        return {"collected": len(cases),
                **{outcome: sum(c.outcome == outcome for c in cases)
                   for outcome in ("passed", "failed", "error", "skipped")}}

    @property
    def ok(self) -> bool:
        return (not self.timed_out and self.returncode == 0 and self.failed == 0
                and self.errors == 0 and self.passed > 0
                and (not self.generated_files
                     or any(c.outcome == "passed" for c in self.generated_cases)))

    def summary(self) -> str:
        if self.timed_out:
            return f"TIMEOUT after {self.timeout_s:g}s"
        text = (f"{self.passed} passed, {self.failed} failed, {self.errors} errors, "
                f"{self.skipped} skipped (rc={self.returncode})")
        generated = self.generated_counts()
        if generated is not None:
            text += (f"; generated: {generated['passed']} passed of "
                     f"{generated['collected']} collected")
        return text

    def failure_report(self, limit: int = 4000) -> str:
        parts = [self.summary()]
        generated = self.generated_counts()
        if generated is not None and generated["passed"] == 0:
            parts.append("No generated test case passed. Existing-suite passes cannot verify "
                         "the generated files. Write runnable tests and check project collection "
                         "rules, deselection and skip conditions.")
        if self.timed_out:
            parts.append("The test run exceeded the time limit and was killed. "
                         "Look for infinite loops, blocking I/O, or very slow tests.")
        for c in self.cases:
            if c.outcome in ("failed", "error"):
                parts.append(f"--- {c.outcome.upper()}: {c.nodeid}\n{c.message.strip()}")
        if not any(c.outcome in ("failed", "error") for c in self.cases):
            parts.append("--- pytest output (tail)\n" + self.output[-2000:])
        text = "\n".join(parts)
        return text if len(text) <= limit else text[: limit - 20] + "\n...[truncated]"

    def to_dict(self) -> dict:
        d = asdict(self)
        d.update(passed=self.passed, failed=self.failed, errors=self.errors,
                 skipped=self.skipped, ok=self.ok, summary=self.summary())
        d["generated"] = self.generated_counts()
        d["output"] = self.output[-3000:]
        return d


@lru_cache(maxsize=None)
def coverage_available(python: str) -> bool:
    return subprocess.run([python, "-c", "import coverage"], capture_output=True).returncode == 0


def clean_env(root: Path) -> dict[str, str]:
    env = {k: v for k, v in os.environ.items() if not any(m in k.upper() for m in _SECRET_MARKERS)}
    for k in ("PYTEST_ADDOPTS", "PYTEST_PLUGINS", "COVERAGE_PROCESS_START", "COVERAGE_FILE"):
        env.pop(k, None)
    paths = [str(root / "src")] if (root / "src").is_dir() else []
    env.update(PYTHONPATH=os.pathsep.join(paths + [str(root)]), PYTHONDONTWRITEBYTECODE="1", PYTHONHASHSEED="0")
    return env


def _run(cmd: list[str], cwd: Path, env: dict, timeout: float) -> tuple[int | None, str, bool]:
    """Collect output, with at most one extra second of POSIX timeout cleanup."""
    proc = subprocess.Popen(cmd, cwd=cwd, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True, errors="replace", start_new_session=True)
    try:
        out, _ = proc.communicate(timeout=timeout)
        return proc.returncode, out, False
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except (ProcessLookupError, AttributeError, PermissionError):
            proc.kill()
        try:
            # A detached helper may retain stdout after the target group dies.
            # POSIX communicate uses synchronous reads that we can stop and close;
            # preserve the existing Windows reader-thread cleanup behavior.
            out, _ = proc.communicate(timeout=1.0 if os.name == "posix" else None)
        except subprocess.TimeoutExpired as exc:
            # TimeoutExpired.output is bytes even in text mode. Preserve complete
            # diagnostics plus a replacement for a character cut off by the kill.
            out = (exc.output or b"").decode(proc.stdout.encoding, errors="replace")
            out = out.replace("\r\n", "\n").replace("\r", "\n")
            proc.stdout.close()
            proc.poll()  # Reap the killed leader without waiting for escaped helpers.
        return None, out or "", True


def parse_junit(path: Path) -> list[CaseResult]:
    root = ET.parse(path).getroot()
    cases: list[CaseResult] = []
    for tc in root.iter("testcase"):
        cls, name = tc.get("classname", ""), tc.get("name", "")
        nodeid = f"{cls}::{name}" if cls else name
        outcome, msg = "passed", ""
        for tag, label in (("failure", "failed"), ("error", "error"), ("skipped", "skipped")):
            el = tc.find(tag)
            if el is not None:
                outcome = label
                msg = (el.get("message") or "") + ("\n" + el.text if el.text else "")
                break
        generated_file = None
        for prop in tc.findall("./properties/property"):
            if prop.get("name") == "testpilot.generated_file":
                generated_file = prop.get("value")
                break
        cases.append(CaseResult(nodeid, outcome, msg, generated_file))
    return cases


def _parse_coverage(path: Path, work: Path) -> CoverageReport:
    data = json.loads(path.read_text())
    files = {}
    resolved = work.resolve()
    for name, info in data.get("files", {}).items():
        p = Path(name)
        if p.is_absolute():
            try:
                name = p.resolve().relative_to(resolved).as_posix()
            except ValueError:
                continue
        files[PurePosixPath(name).as_posix()] = {"executed": info.get("executed_lines", []),
                                                 "missing": info.get("missing_lines", [])}
    return CoverageReport(float(data.get("totals", {}).get("percent_covered", 0.0)), files)


def _safe_join(root: Path, rel: str) -> Path:
    p = (root / rel).resolve()
    if root.resolve() not in p.parents:
        raise ValueError(f"refusing to write outside sandbox: {rel}")
    return p


def run_pytest(repo: str | Path, extra_files: dict[str, str] | None = None, *, timeout: float = 60.0,
               python: str | None = None, coverage: bool | None = None,
               pytest_args: tuple[str, ...] = ()) -> SandboxResult:
    """Copy ``repo`` to a temp dir, add ``extra_files``, run pytest, collect results."""
    python = python or sys.executable
    use_cov = coverage_available(python) if coverage is None else coverage
    with tempfile.TemporaryDirectory(prefix="testpilot-") as td:
        tdp = Path(td)
        work = tdp / "repo"
        shutil.copytree(repo, work, ignore=IGNORE)
        for rel, content in (extra_files or {}).items():
            dest = _safe_join(work, rel)
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(content, encoding="utf-8")
        junit = tdp / "junit.xml"
        options = ["-q", "-p", "no:cacheprovider", "--rootdir", str(work), "-o", "addopts=",
              "-o", "junit_family=xunit2", f"--junitxml={junit}", *pytest_args]
        generated_files = sorted(extra_files or {})
        pt = ["-m", "pytest", *options]
        if generated_files:
            runner = tdp / "generated_pytest.py"
            manifest = tdp / "generated_files.json"
            shutil.copyfile(Path(__file__).with_name("_pytest_generated.py"), runner)
            manifest.write_text(json.dumps({str(_safe_join(work, rel)): rel for rel in generated_files}),
                                encoding="utf-8")
            pt = [str(runner), str(manifest), *options]
        data_file = tdp / ".coverage"
        if use_cov:
            cmd = [python, "-m", "coverage", "run", f"--data-file={data_file}", f"--source={work}",
                   f"--omit={_OMIT}", *pt]
        else:
            cmd = [python, *pt]
        env = clean_env(work)
        t0 = time.monotonic()
        rc, out, timed_out = _run(cmd, work, env, timeout)
        dur = time.monotonic() - t0
        junit_available = junit.exists() and not timed_out
        cases = parse_junit(junit) if junit_available else []
        cov = None
        if use_cov and not timed_out:
            # Reserve the report destination after pytest so a failed report
            # command cannot reuse a file left by the test run.
            with tempfile.TemporaryDirectory(prefix="coverage-report-", dir=tdp) as report_dir:
                cov_json = Path(report_dir) / "cov.json"
                crc, _, _ = _run([python, "-m", "coverage", "json", f"--data-file={data_file}", "-o", str(cov_json), "-q"],
                                 work, env, 60)
                # Exit 2 can mean a complete report is below configured fail_under.
                cov = _parse_coverage(cov_json, work) if crc in (0, 2) and cov_json.exists() else None
        return SandboxResult(rc, timed_out, round(dur, 3), timeout, out, cases, cov,
                             generated_files, junit_available)
